WITH customer_perf AS ( SELECT cr.cr_returning_customer_sk AS returning_customer_id, COUNT(DISTINCT cs.cs_order_number) AS total_orders, SUM(cs.cs_net_paid_inc_tax) AS total_sales_amount, COALESCE(SUM(cr.cr_refunded_cash), 0) AS total_refunded_cash, MIN(cr.cr_returned_date_sk) AS min_return_date FROM catalog_returns cr JOIN catalog_sales cs ON cr.cr_order_number = cs.cs_order_number AND cr.cr_item_sk = cs.cs_item_sk JOIN item i ON cr.cr_item_sk = i.i_item_sk GROUP BY cr.cr_returning_customer_sk ) SELECT returning_customer_id, total_orders, total_sales_amount, total_refunded_cash, (total_sales_amount - total_refunded_cash) AS net_total, CASE WHEN (total_sales_amount - total_refunded_cash) > 10000 THEN 'High Value' ELSE 'Regular' END AS customer_category, ROW_NUMBER() OVER (ORDER BY (total_sales_amount - total_refunded_cash) DESC) AS sales_rank, CASE WHEN min_return_date BETWEEN 20220101 AND 20221231 THEN '2022' ELSE 'Other' END AS year_category FROM customer_perf
